/* SIR epidemic on networks — agent-05 (v5.3)
 *
 * A disease spreads over a contact network. Each node is a person in one of
 * three states: Susceptible (S, can catch it), Infected (I, infectious), or
 * Recovered (R, immune, can't catch or spread). Time ticks in discrete rounds:
 * every infected node tries to transmit to each susceptible neighbour with
 * probability beta; and each infected node recovers with probability gamma.
 * The epidemic is over once no infectious node remains.
 *
 * The hosting network is generated by one of three classic random-graph models:
 *   - Erdos-Renyi (ER): every pair of N nodes linked with probability p
 *     (a "mean-field" soup — the textbook model where the epidemic threshold is
 *     beta/gamma > 1/<degree>).
 *   - Watts-Strogatz (small-world): a ring lattice rewired with probability r —
 *     short paths AND local clustering, the structure real social contact nets
 *     seem to have.
 *   - Barabasi-Albert (scale-free): growth + preferential attachment — a few
 *     hubs with huge degree, which makes the whole population vulnerable because
 *     the hubs act as super-spreaders.
 *
 * This is a *different mechanism class* from the rest of the zoo: it is the
 * first graph/substrate-based agent model, with a network-generation step and a
 * stochastic compartmental contagion dynamics. Node positions are a deterministic
 * force-directed-ish layout (Fruchterman-Reingold, seeded) so a share link
 * reproduces the exact same network AND epidemic. Deterministic: every random
 * choice (edge rewiring, attachment, initial seeding, transmission, recovery) is
 * driven by a single mulberry32 PRNG seeded from "Seed". Dual-mode: under Node
 * it runs a determinism + outbreak self-test.
 */
(function (global) {
  "use strict";

  // --- deterministic PRNG -------------------------------------------------
  function mulberry32(a) {
    a = a >>> 0;
    return function () {
      a |= 0; a = (a + 0x6d2b79f5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  // --- graph generators ---------------------------------------------------
  // Each returns { N, edges: [[i,j], ...] } with undirected, simple edges.

  function makeER(N, p, rng) {
    var edges = [];
    for (var i = 0; i < N; i++) {
      for (var j = i + 1; j < N; j++) {
        if (rng() < p) edges.push([i, j]);
      }
    }
    return { N: N, edges: edges };
  }

  // Watts-Strogatz small-world: ring lattice k-nearest, rewire each edge with
  // probability r (beta in the literature).
  function makeWS(N, k, r, rng) {
    k = Math.max(2, Math.min(k, N - 1));
    if (k % 2 === 1) k += 1; // keep even for a clean ring
    var adj = [];
    for (var i = 0; i < N; i++) adj[i] = [];
    // ring lattice: link each node to its k/2 nearest neighbours each side
    for (i = 0; i < N; i++) {
      for (var mm = 1; mm <= k / 2; mm++) {
        var j = (i + mm) % N;
        if (j < 0) j += N;
        if (adj[i].indexOf(j) < 0) { adj[i].push(j); adj[j].push(i); }
      }
    }
    var keyOf = function (a, b) { return a < b ? a + "_" + b : b + "_" + a; };
    var seen = {};
    for (i = 0; i < N; i++) {
      // iterate a snapshot of the current neighbour list
      var neigh = adj[i].slice();
      for (var q = 0; q < neigh.length; q++) {
        var jj = neigh[q];
        if (i < jj && rng() < r) {
          // rewire (i, jj) -> (i, w): w not i, not already linked to i, and
          // not already an edge between i and w.
          var w = -1;
          for (var tries = 0; tries < 64; tries++) {
            var cand = Math.floor(rng() * N);
            if (cand !== i && adj[i].indexOf(cand) < 0 && keyOf(i, cand) !== keyOf(i, jj)) {
              w = cand; break;
            }
          }
          if (w >= 0) {
            var idx = adj[i].indexOf(jj); if (idx >= 0) adj[i].splice(idx, 1);
            idx = adj[jj].indexOf(i); if (idx >= 0) adj[jj].splice(idx, 1);
            adj[i].push(w); adj[w].push(i);
          }
        }
      }
    }
    var edges = [];
    for (i = 0; i < N; i++) {
      for (q = 0; q < adj[i].length; q++) {
        var u = adj[i][q];
        var kk = keyOf(i, u);
        if (i < u && !seen[kk]) { seen[kk] = 1; edges.push([i, u]); }
      }
    }
    return { N: N, edges: edges };
  }

  // Barabasi-Albert scale-free: start from a small connected core, then add
  // nodes one at a time, each linking to m existing nodes chosen with
  // probability proportional to their current degree (preferential attachment).
  function makeBA(N, m, rng) {
    m = Math.max(1, Math.min(m, N - 1));
    var coreK = Math.max(m + 1, 3);
    if (N < coreK) N = coreK;
    var deg = [];
    var adj = [];
    var edges = [];
    for (var i = 0; i < coreK; i++) { deg[i] = 0; adj[i] = []; }
    for (i = 0; i < coreK; i++) {
      for (var j = i + 1; j < coreK; j++) {
        edges.push([i, j]); adj[i].push(j); adj[j].push(i); deg[i]++; deg[j]++;
      }
    }
    var total = 2 * edges.length; // sum of degrees
    function pickTarget() {
      if (total <= 0) return Math.floor(rng() * deg.length);
      var t = rng() * (total + 1);
      var acc = 0;
      for (var x = 0; x < deg.length; x++) {
        acc += deg[x];
        if (acc >= t) return x;
      }
      return deg.length - 1;
    }
    for (i = coreK; i < N; i++) {
      deg[i] = 0; adj[i] = [];
      var targets = [];
      var guard = 0;
      while (targets.length < m && guard < 512) {
        guard++;
        var tgt = pickTarget();
        if (tgt !== i && adj[i].indexOf(tgt) < 0 && targets.indexOf(tgt) < 0) {
          targets.push(tgt);
        }
      }
      for (var q = 0; q < targets.length; q++) {
        var u = targets[q];
        edges.push([i, u]); adj[i].push(u); adj[u].push(i); deg[i]++; deg[u]++;
        total += 2;
      }
    }
    return { N: N, edges: edges };
  }

  function generateGraph(type, N, param, rng) {
    if (type === "er") return makeER(N, param, rng);
    if (type === "ws") return makeWS(N, 6, param, rng);
    if (type === "ba") return makeBA(N, Math.max(1, Math.round(param)), rng);
    return makeER(N, param, rng);
  }

  // --- force-directed layout (deterministic, seeded) ----------------------
  // Fruchterman-Reingold-ish spring/repulsion over maxIter steps.
  function layoutEdges(N, edges, rng, W, H, maxIter) {
    var xs = new Float64Array(N), ys = new Float64Array(N);
    for (var i = 0; i < N; i++) {
      xs[i] = (0.5 + (rng() - 0.5) * 0.9) * W;
      ys[i] = (0.5 + (rng() - 0.5) * 0.9) * H;
    }
    var adj = [];
    for (i = 0; i < N; i++) adj[i] = [];
    for (i = 0; i < edges.length; i++) {
      adj[edges[i][0]].push(edges[i][1]);
      adj[edges[i][1]].push(edges[i][0]);
    }
    var area = W * H;
    var k = Math.sqrt(area / (N + 1)); // ideal edge length
    var cool = 1.0;
    var temp = 0.12 * Math.min(W, H);
    maxIter = maxIter || 320;
    for (var it = 0; it < maxIter; it++) {
      var dx = new Float64Array(N), dy = new Float64Array(N);
      // repulsion (all pairs, fine for N up to a few hundred)
      for (i = 0; i < N; i++) {
        for (var j = i + 1; j < N; j++) {
          var ddx = xs[i] - xs[j], ddy = ys[i] - ys[j];
          var d2 = ddx * ddx + ddy * ddy + 0.01;
          var d = Math.sqrt(d2);
          var rep = (k * k) / d;
          var fx = (ddx / d) * rep, fy = (ddy / d) * rep;
          dx[i] += fx; dy[i] += fy; dx[j] -= fx; dy[j] -= fy;
        }
      }
      // attraction along edges
      for (i = 0; i < edges.length; i++) {
        var a = edges[i][0], b = edges[i][1];
        var adx = xs[a] - xs[b], ady = ys[a] - ys[b];
        var dist = Math.sqrt(adx * adx + ady * ady) + 0.01;
        var att = (dist * dist) / k;
        var afx = (adx / dist) * att, afy = (ady / dist) * att;
        dx[a] -= afx; dy[a] -= afy; dx[b] += afx; dy[b] += afy;
      }
      // integrate with temperature cap, then rescale into the box
      for (i = 0; i < N; i++) {
        var dl = Math.sqrt(dx[i] * dx[i] + dy[i] * dy[i]) + 1e-6;
        var disp = Math.min(dl, temp);
        xs[i] += (dx[i] / dl) * disp;
        ys[i] += (dy[i] / dl) * disp;
        xs[i] = Math.max(8, Math.min(W - 8, xs[i]));
        ys[i] = Math.max(8, Math.min(H - 8, ys[i]));
      }
      temp *= Math.pow(0.02, 1 / maxIter); // cool toward ~2% of initial
    }
    return { xs: xs, ys: ys, adj: adj };
  }

  // --- the SIR model (no DOM) ---------------------------------------------
  function SIRModel(opts) {
    opts = opts || {};
    this.N = opts.N || 120;
    this.graphType = opts.graphType || "er";
    this.gparam = (opts.gparam != null) ? opts.gparam : 0.08;
    this.beta = (opts.beta != null) ? opts.beta : 0.18;
    this.gamma = (opts.gamma != null) ? opts.gamma : 0.05;
    this.infected0 = (opts.infected0 != null) ? opts.infected0 : 2;
    this.seed = (opts.seed != null) ? opts.seed >>> 0 : 1;
    this.W = 480; this.H = 480;
    this.maxIter = 320;

    this.rng = mulberry32(this.seed);
    var g = generateGraph(this.graphType, this.N, this.gparam, this.rng);
    this.edges = g.edges;
    var lay = layoutEdges(g.N, g.edges, this.rng, this.W, this.H, this.maxIter);
    this.xs = lay.xs; this.ys = lay.ys; this.adj = lay.adj;

    this.state = new Int8Array(this.N); // 0 S, 1 I, 2 R
    this.time = 0;
    this.newInfections = 0;
    this._init();
    // history of compartment counts for the chart
    this.history = [this.counts()];
  }

  SIRModel.prototype._init = function () {
    this.state.fill(0);
    var order = [];
    for (var i = 0; i < this.N; i++) order.push(i);
    // Fisher-Yates with the same rng so the seed fully pins the seeding
    for (i = this.N - 1; i > 0; i--) {
      var j = Math.floor(this.rng() * (i + 1));
      var tmp = order[i]; order[i] = order[j]; order[j] = tmp;
    }
    var n0 = Math.max(1, Math.min(this.infected0, this.N));
    for (i = 0; i < n0; i++) this.state[order[i]] = 1;
    this.time = 0;
    this.newInfections = 0;
  };

  SIRModel.prototype.counts = function () {
    var S = 0, I = 0, R = 0;
    for (var i = 0; i < this.N; i++) {
      if (this.state[i] === 0) S++;
      else if (this.state[i] === 1) I++;
      else R++;
    }
    return { S: S, I: I, R: R, t: this.time };
  };

  // One transmission+recovery round.
  SIRModel.prototype.step = function () {
    var state = this.state, adj = this.adj, beta = this.beta, gamma = this.gamma;
    var rng = this.rng, N = this.N;
    var next = state.slice();
    var newlyInfected = 0;
    // transmission
    for (var i = 0; i < N; i++) {
      if (state[i] !== 1) continue;
      var nb = adj[i];
      for (var q = 0; q < nb.length; q++) {
        var j = nb[q];
        if (state[j] === 0 && rng() < beta) { next[j] = 1; newlyInfected++; }
      }
    }
    // recovery
    for (i = 0; i < N; i++) {
      if (state[i] === 1 && rng() < gamma) next[i] = 2;
    }
    this.state = next;
    this.time++;
    this.newInfections = newlyInfected;
    var c = this.counts();
    this.history.push(c);
    return c;
  };

  SIRModel.prototype.done = function () {
    for (var i = 0; i < this.N; i++) if (this.state[i] === 1) return false;
    return true;
  };

  SIRModel.prototype.metrics = function () {
    var c = this.counts();
    // average degree
    var deg = 0;
    for (var i = 0; i < this.N; i++) deg += this.adj[i].length;
    var meanDeg = deg / this.N;
    return {
      S: c.S, I: c.I, R: c.R,
      time: this.time,
      attackRate: (1 - c.S / this.N),
      meanDegree: meanDeg,
      edges: this.edges.length,
      N: this.N
    };
  };

  // --- node self-test (determinism + an actual epidemic happens) ----------
  if (typeof module !== "undefined" && module.exports) {
    module.exports = {
      SIRModel: SIRModel, mulberry32: mulberry32,
      generateGraph: generateGraph, layoutEdges: layoutEdges
    };
    if (require.main === module) {
      function fingerprint(m) {
        // sum of node positions + state gives a stable reproduction signature
        var fp = 0;
        for (var i = 0; i < m.N; i++) fp += (m.xs[i] * 1e3 + m.ys[i]) * (m.state[i] + 1);
        return fp;
      }
      function runEpidemic(seed, type, beta, gamma, N) {
        var m = new SIRModel({ seed: seed, graphType: type, gparam: type === "ws" ? 0.15 : 0.08, beta: beta, gamma: gamma, N: N, infected0: 2 });
        var guard = 0;
        while (!m.done() && guard < 4000) { m.step(); guard++; }
        return m;
      }
      var A = runEpidemic(12345, "er", 0.2, 0.05, 120);
      var B = runEpidemic(12345, "er", 0.2, 0.05, 120);
      var C = runEpidemic(12346, "er", 0.2, 0.05, 120);
      var sameSeed = Math.abs(fingerprint(A) - fingerprint(B)) < 1e-6 && A.metrics().time === B.metrics().time;
      var diffSeed = Math.abs(fingerprint(A) - fingerprint(C)) > 1e-3;
      // an epidemic with beta/gamma*<k> > 1 should infect a substantial fraction
      var attack = A.metrics().attackRate;
      var outbreak = attack > 0.2;
      // also verify a tiny-beta run fizzles (below threshold)
      var D = runEpidemic(777, "er", 0.005, 0.2, 120);
      var fizzle = D.metrics().attackRate < attack;
      var ok = sameSeed && diffSeed && outbreak && fizzle;
      console.log(JSON.stringify({
        A_attackRate: +attack.toFixed(3),
        D_attackRate: +D.metrics().attackRate.toFixed(3),
        A_time: A.metrics().time,
        sameSeedIdentical: sameSeed,
        diffSeedDiverges: diffSeed,
        outbreakHappens: outbreak,
        fizzleBelowThreshold: fizzle,
        ok: ok
      }, null, 2));
      process.exit(ok ? 0 : 1);
    }
    return;
  }

  // --- browser UI ---------------------------------------------------------
  if (typeof document === "undefined") return;

  function $(id) { return document.getElementById(id); }

  var canvas, ctx, model, raf = null, running = true, finished = false;
  var state = {
    seed: 12345, graphType: "er", gparam: 0.08, beta: 0.18, gamma: 0.05,
    N: 120, infected0: 2, palette: "classic", speed: 1, showEdges: true
  };

  var PALETTES = {
    classic: { S: [90, 120, 180], I: [220, 70, 60], R: [120, 170, 120], bg: [16, 18, 24], edge: [70, 80, 100] },
    ice:    { S: [70, 140, 210], I: [240, 110, 90], R: [150, 200, 200], bg: [10, 18, 30], edge: [55, 75, 105] },
    ember:  { S: [200, 150, 90], I: [255, 90, 50], R: [180, 120, 90], bg: [22, 14, 10], edge: [90, 60, 44] },
    mono:   { S: [120, 120, 130], I: [240, 240, 245], R: [90, 95, 105], bg: [20, 21, 26], edge: [60, 64, 74] }
  };

  var COLORS = { S: "#5a78b4", I: "#dc463c", R: "#78aa78" };

  function draw() {
    if (!model) return;
    var W = canvas.width, H = canvas.height;
    var pal = PALETTES[state.palette] || PALETTES.classic;
    ctx.fillStyle = "rgb(" + pal.bg.join(",") + ")";
    ctx.fillRect(0, 0, W, H);

    // edges
    if (state.showEdges) {
      ctx.strokeStyle = "rgba(" + pal.edge.join(",") + ",0.5)";
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      var E = model.edges;
      for (var e = 0; e < E.length; e++) {
        var a = E[e][0], b = E[e][1];
        ctx.moveTo(model.xs[a], model.ys[a]);
        ctx.lineTo(model.xs[b], model.ys[b]);
      }
      ctx.stroke();
    }

    // nodes coloured by state
    for (var i = 0; i < model.N; i++) {
      var st = model.state[i];
      var col = st === 0 ? pal.S : (st === 1 ? pal.I : pal.R);
      var r = st === 1 ? 3.2 : 2.4; // infected pop a little
      ctx.fillStyle = "rgb(" + col.join(",") + ")";
      ctx.beginPath();
      ctx.arc(model.xs[i], model.ys[i], r, 0, 6.283185307179586);
      ctx.fill();
    }
  }

  function drawChart() {
    var cv = $("chart");
    if (!cv) return;
    var g = cv.getContext("2d");
    var W = cv.width, H = cv.height;
    g.fillStyle = "#10121a"; g.fillRect(0, 0, W, H);
    var hist = model.history;
    if (!hist || !hist.length) return;
    var maxN = model.N;
    var n = hist.length;
    var dx = W / Math.max(1, n - 1);
    function plot(key, color) {
      g.strokeStyle = color; g.lineWidth = 2; g.beginPath();
      for (var i = 0; i < n; i++) {
        var x = i * dx;
        var y = H - (hist[i][key] / maxN) * H;
        if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
      }
      g.stroke();
    }
    plot("S", COLORS.S);
    plot("I", COLORS.I);
    plot("R", COLORS.R);
  }

  function readout() {
    var m = model.metrics();
    var pc = (m.attackRate * 100).toFixed(1);
    var note;
    if (m.I === 0 && m.time > 0) {
      note = "epidemic over — final attack rate " + pc + "% reached immunity";
      finished = true;
    } else if (m.I === 0) {
      note = "no infection (seed not infectious?)";
    } else {
      note = "spreading — " + m.I + " infectious, herd immunity building";
      finished = false;
    }
    $("readout").innerHTML =
      "<div class=\"ro-row\"><span>round</span><b>" + m.time + "</b></div>" +
      "<div class=\"ro-row\"><span>epidemic threshold &beta;/&gamma;/&lang;k&rang;</span><b>" + (m.beta !== undefined ? (state.beta / state.gamma / m.meanDegree).toFixed(2) : "?") + "</b></div>" +
      "<div class=\"ro-row\"><span>mean degree &lang;k&rang;</span><b>" + m.meanDegree.toFixed(2) + "</b></div>" +
      "<div class=\"ro-row\"><span>edges</span><b>" + m.edges + "</b></div>" +
      "<div class=\"ro-row\"><span>susceptible (S)</span><b style=\"color:" + COLORS.S + "\">" + m.S + "</b></div>" +
      "<div class=\"ro-row\"><span>infectious (I)</span><b style=\"color:" + COLORS.I + "\">" + m.I + "</b></div>" +
      "<div class=\"ro-row\"><span>recovered (R)</span><b style=\"color:" + COLORS.R + "\">" + m.R + "</b></div>" +
      "<div class=\"ro-row\"><span>final attack rate</span><b>" + pc + "%</b></div>" +
      "<div class=\"ro-note\">" + note + "</div>";
  }

  function frame() {
    if (running && model && !model.done()) {
      for (var i = 0; i < state.speed && !model.done(); i++) model.step();
      draw(); drawChart(); readout();
    }
    raf = requestAnimationFrame(frame);
  }

  function setRunning(on) {
    running = on;
    var btn = $("play");
    btn.textContent = on ? "⏸ Pause" : "▶ Play";
    btn.setAttribute("aria-pressed", on ? "true" : "false");
  }

  function rebuild() {
    model = new SIRModel({
      seed: state.seed, graphType: state.graphType, gparam: state.gparam,
      beta: state.beta, gamma: state.gamma, N: state.N, infected0: state.infected0
    });
    finished = false;
    draw(); drawChart(); readout();
  }

  function encodeState() {
    return [state.seed, state.graphType, state.gparam, state.beta, state.gamma, state.N, state.infected0, state.palette, state.showEdges ? 1 : 0].join(",");
  }

  function decodeState(hash) {
    var parts = hash.replace(/^#/, "").split(",");
    if (parts.length < 9) return false;
    var s = state;
    s.seed = parseInt(parts[0], 10) || 1;
    s.graphType = ["er", "ws", "ba"].indexOf(parts[1]) >= 0 ? parts[1] : "er";
    s.gparam = parseFloat(parts[2]); if (!(s.gparam > 0)) s.gparam = 0.08;
    s.beta = parseFloat(parts[3]); if (!(s.beta >= 0)) s.beta = 0.18;
    s.gamma = parseFloat(parts[4]); if (!(s.gamma >= 0)) s.gamma = 0.05;
    s.N = [60, 120, 200, 320].indexOf(parseInt(parts[5], 10)) >= 0 ? parseInt(parts[5], 10) : 120;
    s.infected0 = Math.max(1, Math.min(parseInt(parts[6], 10) || 2, s.N));
    s.palette = PALETTES[parts[7]] ? parts[7] : "classic";
    s.showEdges = parts[8] === "1";
    return true;
  }

  function applyControls() {
    $("seed").value = state.seed; $("seed-val").textContent = state.seed;
    $("graphType").value = state.graphType;
    $("gparam").value = state.gparam; $("gparam-val").textContent = (+state.gparam).toFixed(3);
    $("beta").value = state.beta; $("beta-val").textContent = (+state.beta).toFixed(2);
    $("gamma").value = state.gamma; $("gamma-val").textContent = (+state.gamma).toFixed(2);
    $("N").value = String(state.N);
    $("infected0").value = state.infected0; $("infected0-val").textContent = state.infected0;
    $("palette").value = state.palette;
    $("showEdges").checked = state.showEdges;
  }

  function syncFromControls() {
    state.seed = parseInt($("seed").value, 10) || 1;
    state.graphType = $("graphType").value;
    state.gparam = parseFloat($("gparam").value);
    state.beta = parseFloat($("beta").value);
    state.gamma = parseFloat($("gamma").value);
    state.N = parseInt($("N").value, 10);
    state.infected0 = parseInt($("infected0").value, 10);
    state.palette = $("palette").value;
    state.showEdges = $("showEdges").checked;
    state.speed = parseInt($("speed").value, 10);
  }

  function msg(t) { $("msg").textContent = t || ""; }

  function init() {
    canvas = $("sir");
    ctx = canvas.getContext("2d");

    if (location.hash && decodeState(location.hash)) applyControls();

    var presets = {
      epidemic: { graphType: "er", gparam: 0.05, beta: 0.22, gamma: 0.04, N: 120, infected0: 2 },
      threshold: { graphType: "er", gparam: 0.05, beta: 0.03, gamma: 0.15, N: 120, infected0: 2 },
      smallworld: { graphType: "ws", gparam: 0.18, beta: 0.16, gamma: 0.05, N: 200, infected0: 2 },
      scalefree: { graphType: "ba", gparam: 4, beta: 0.12, gamma: 0.04, N: 200, infected0: 2 },
      slowburn: { graphType: "er", gparam: 0.12, beta: 0.10, gamma: 0.02, N: 120, infected0: 1 }
    };
    Array.prototype.forEach.call(document.querySelectorAll(".preset"), function (btn) {
      btn.addEventListener("click", function () {
        var p = presets[btn.getAttribute("data-preset")];
        if (!p) return;
        Object.assign(state, p);
        applyControls();
        rebuild();
        msg("Preset loaded — press Play if paused.");
      });
    });

    ["seed", "graphType", "gparam", "beta", "gamma", "N", "infected0", "palette", "showEdges", "speed"].forEach(function (id) {
      $(id).addEventListener("input", function () {
        syncFromControls();
        if (id === "palette" || id === "showEdges" || id === "speed") { draw(); drawChart(); return; }
        rebuild();
      });
    });

    $("play").addEventListener("click", function () { setRunning(!running); });
    $("step").addEventListener("click", function () {
      setRunning(false);
      if (!model.done()) { model.step(); draw(); drawChart(); readout(); }
    });
    $("reset").addEventListener("click", function () { rebuild(); });
    $("restart").addEventListener("click", function () {
      // new network, same seed rules — re-run from freshly seeded patient zero
      rebuild();
    });
    $("share").addEventListener("click", function () {
      syncFromControls();
      var url = location.origin + location.pathname + "#" + encodeState();
      history.replaceState(null, "", "#" + encodeState());
      if (navigator.clipboard) {
        navigator.clipboard.writeText(url).then(
          function () { msg("Share link copied — it reproduces this exact network and run."); },
          function () { msg("Share link in the address bar."); }
        );
      } else { msg("Share link in the address bar."); }
    });

    rebuild();
    setRunning(true);
    frame();
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else { init(); }

  global.SIRModel = SIRModel;
})(typeof window !== "undefined" ? window : (typeof globalThis !== "undefined" ? globalThis : this));
